  <header class="section-head"><div><span class="eyebrow">SWIPE · MATCH · DISCOVER</span><h2>Trust the feeling.</h2></div><p>Pass, save for later, or love it.</p></header>
  <div class="match-banner" id="matchBanner"><span>♥ YOU BOTH LOVE</span><h3 id="matchName">Luna is a match!</h3></div>
  <div class="swipe-shell"><article class="swipe-card" id="swipeCard"></article><div><div class="swipe-controls"><button class="swipe-control" data-choice="pass"><b>×</b><span><strong>Pass</strong><small>Not this one</small></span></button><button class="swipe-control maybe" data-choice="maybe"><b>◆</b><span><strong>Maybe</strong><small>Save for later</small></span></button><button class="swipe-control love" data-choice="love"><b>♥</b><span><strong>Love</strong><small>Add to favorites</small></span></button></div><div class="decision-count" id="decisionCount"></div><button class="pill" id="resetDeck" type="button" style="width:100%">Reset reviewed names</button></div></div>
 </section>

 <section class="view" id="view-favorites" data-view="favorites">
  <header class="section-head"><div><span class="eyebrow">YOUR PRIVATE SHORTLIST</span><h2>The names that stayed with you.</h2></div><p>Saved only on this device.</p></header>
  <div class="stats" id="favoriteStats"></div><div class="favorite-grid" id="favoritesGrid" style="margin-top:18px"></div>
  <header class="section-head"><div><span class="eyebrow">DOUBLE THE JOY</span><h2>Twin pair ideas.</h2></div><p>Balanced combinations from your list.</p></header><div class="twin-grid" id="twinGrid"></div>
 </section>

 <section class="view" id="view-couple" data-view="couple">
  <header class="section-head"><div><span class="eyebrow">COUPLE MODE</span><h2>Better decisions, together.</h2></div><p>Only shared loves become matches.</p></header>
  <div class="couple-hero"><section class="panel couple-copy"><span class="eyebrow">PRIVATE BY DESIGN</span><h2>Name it<br>together.</h2><p>Your likes remain private. When you and your partner love the same name, it appears here as a match.</p><div class="stats" id="coupleStats"></div></section><section class="panel couple-code"><label for="partnerName">PARTNER NAME</label><input class="partner-input" id="partnerName" value="My partner"><label style="margin-top:24px">YOUR COUPLE CODE</label><button class="code-button" type="button" id="copyCode"><span id="coupleCode">BBN-LOVE1</span><span>Copy ⧉</span></button><p style="color:var(--muted);font-size:.78rem">Version 1.0 keeps demo partner picks on this device. The invite code creates the handoff point for account sync later.</p><button class="pill" type="button" id="demoPartner">Refresh demo partner picks</button></section></div>
  <header class="section-head"><div><span class="eyebrow">SHARED FAVORITES</span><h2>Your matches.</h2></div></header><div class="match-grid" id="matchesGrid"></div>
 </section>
</main>

<nav class="bottom-nav" aria-label="Mobile app navigation"><button class="active" data-nav="discover"><b>✦</b>Discover</button><button data-nav="swipe"><b>▣</b>Swipe</button><button data-nav="favorites"><b>♥</b>Favorites</button><button data-nav="couple"><b>♟</b>Together</button></nav>
<dialog class="modal" id="nameModal"><div class="modal-inner"><button class="close" id="closeModal" aria-label="Close">×</button><div id="modalContent"></div></div></dialog>
<dialog class="modal" id="preferencesModal"><div class="modal-inner"><button class="close" id="closePreferences" aria-label="Close">×</button><span class="eyebrow">TUNE YOUR PICKS</span><h2 style="font-size:2.5rem;margin:.5rem 0">What feels like you?</h2><p style="color:var(--muted)">Choose a few qualities. Recommendations update instantly.</p><div class="vibe-wrap" id="preferenceVibes"></div><button class="action primary" id="savePreferences" style="width:100%;margin-top:22px">Update my picks</button></div></dialog>
<div class="toast" id="toast" role="status"></div>
<script>
const names=<?=json_encode($names,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
const allVibes=[...new Set(names.flatMap(name=>name.vibes))].sort();
const storageKey='beyond-baby-names-v1';
const defaults={favorites:[],choices:{},vibes:['Rare','Gentle'],partnerLikes:['Luna','Ezra','Kai','Elsa'],partnerName:'My partner'};
let state={...defaults,...readState()},activeStyle='',swipeName=null,pickOffset=0;
const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)];
function readState(){try{return JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{return {}}}
function persist(){localStorage.setItem(storageKey,JSON.stringify(state))}
function escapeHTML(value){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function isFavorite(name){return state.favorites.includes(name)}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1800)}
function toggleFavorite(name,event){event?.stopPropagation();state.favorites=isFavorite(name)?state.favorites.filter(item=>item!==name):[...state.favorites,name];persist();renderAll();toast(isFavorite(name)?`${name} saved`:`${name} removed`)}
function nav(view){$$('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===view));history.replaceState(null,'',`#${view}`);if(view==='swipe')renderSwipe();if(view==='favorites')renderFavorites();if(view==='couple')renderCouple();scrollTo({top:innerWidth<620?520:640,behavior:'smooth'})}
$$('[data-nav]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();nav(button.dataset.nav)}));
function score(name){const vibeScore=name.vibes.filter(vibe=>state.vibes.includes(vibe)).length*30;const origins=names.filter(item=>state.favorites.includes(item.name)).map(item=>item.origin);return vibeScore+(origins.includes(name.origin)?18:0)+name.popularity/5}
function recommendations(){return [...names].sort((a,b)=>score(b)-score(a)).slice(pickOffset,pickOffset+3).concat([...names].sort((a,b)=>score(b)-score(a)).slice(0,Math.max(0,pickOffset+3-names.length))).slice(0,3)}
function filteredNames(){const query=$('#search').value.trim().toLowerCase(),origin=$('#origin').value;return names.filter(name=>(!query||[name.name,name.meaning,name.origin,...name.vibes].join(' ').toLowerCase().includes(query))&&(!activeStyle||name.style===activeStyle)&&(!origin||name.origin===origin))}
function heartButton(name){return `<button class="heart ${isFavorite(name.name)?'saved':''}" type="button" data-heart="${escapeHTML(name.name)}" aria-label="${isFavorite(name.name)?'Remove':'Save'} ${escapeHTML(name.name)}">${isFavorite(name.name)?'♥':'♡'}</button>`}
function bindCards(scope=document){scope.querySelectorAll('[data-name]').forEach(card=>card.addEventListener('click',()=>openName(card.dataset.name)));scope.querySelectorAll('[data-heart]').forEach(button=>button.addEventListener('click',event=>toggleFavorite(button.dataset.heart,event)))}
function renderDiscover(){const list=filteredNames();$('#count').textContent=`${list.length} name${list.length===1?'':'s'}`;$('#discoverSummary').textContent=`${list.length} names to explore`;$('#results').innerHTML=list.length?list.map(name=>`<article class="name-card" data-name="${escapeHTML(name.name)}">${heartButton(name)}<span class="tag">${escapeHTML(name.origin.toUpperCase())} · ${escapeHTML(name.style.toUpperCase())}</span><h3>${escapeHTML(name.name)}</h3><p>${escapeHTML(name.meaning)}</p><div class="vibes">${name.vibes.map(v=>`<span>${escapeHTML(v)}</span>`).join('')}</div></article>`).join(''):'<div class="empty">No names match those filters. Try a different feeling.</div>';$('#recommendations').innerHTML=recommendations().map(name=>`<article class="recommendation" data-name="${escapeHTML(name.name)}">${heartButton(name)}<span class="tag">${escapeHTML(name.origin.toUpperCase())}</span><h3>${escapeHTML(name.name)}</h3><p>${escapeHTML(name.meaning)}</p></article>`).join('');bindCards($('#view-discover'))}
function renderVibes(){const html=allVibes.map(v=>`<button type="button" class="vibe ${state.vibes.includes(v)?'active':''}" data-vibe="${escapeHTML(v)}">${escapeHTML(v)}</button>`).join('');$('#vibeFilters').innerHTML=html;$('#preferenceVibes').innerHTML=html;$$('[data-vibe]').forEach(button=>button.addEventListener('click',()=>{state.vibes=state.vibes.includes(button.dataset.vibe)?state.vibes.filter(v=>v!==button.dataset.vibe):[...state.vibes,button.dataset.vibe];persist();renderVibes();renderDiscover()}))}
function nextSwipe(){const available=names.filter(name=>!state.choices[name.name]);swipeName=available[0]||null}
function renderSwipe(){nextSwipe();const card=$('#swipeCard');if(!swipeName){card.innerHTML='<div class="empty" style="margin:auto;color:#fff">You reviewed every name.<br>Reset the deck to begin again.</div>'}else{card.innerHTML=`<div class="topline"><span class="tag">${escapeHTML(swipeName.origin.toUpperCase())}</span><span>${escapeHTML(swipeName.style)}</span></div><div class="name-symbol">✦</div><h2>${escapeHTML(swipeName.name)}</h2><p class="meaning">${escapeHTML(swipeName.meaning)}</p><p class="pronounce">${escapeHTML(swipeName.pronunciation)}</p><div class="swipe-vibes">${swipeName.vibes.map(v=>`<span>${escapeHTML(v)}</span>`).join('')}</div>`}$('#decisionCount').textContent=`${Object.keys(state.choices).length} reviewed · ${matches().length} matches`}
function choose(choice){if(!swipeName)return;state.choices[swipeName.name]=choice;if(choice==='love'&&!isFavorite(swipeName.name))state.favorites.push(swipeName.name);const matched=choice==='love'&&state.partnerLikes.includes(swipeName.name);persist();if(matched){$('#matchName').textContent=`${swipeName.name} is a match!`;$('#matchBanner').classList.add('show');setTimeout(()=>$('#matchBanner').classList.remove('show'),3200)}renderAll()}
$$('[data-choice]').forEach(button=>button.addEventListener('click',()=>choose(button.dataset.choice)));
function matches(){return names.filter(name=>state.favorites.includes(name.name)&&state.partnerLikes.includes(name.name))}
function twinPairs(favorites){const pairs=[];for(let i=0;i<favorites.length;i++)for(let j=i+1;j<favorites.length;j++){const a=favorites[i],b=favorites[j],shared=a.vibes.some(v=>b.vibes.includes(v)),balanced=Math.abs(a.name.length-b.name.length)<=2;if(shared||balanced)pairs.push([a,b])}return pairs.slice(0,6)}
function renderFavorites(){const favorites=names.filter(name=>state.favorites.includes(name.name)),pairs=twinPairs(favorites);$('#favoriteStats').innerHTML=`<div class="stat"><strong>${favorites.length}</strong><span>SAVED</span></div><div class="stat"><strong>${matches().length}</strong><span>MATCHES</span></div><div class="stat"><strong>${new Set(favorites.map(n=>n.origin)).size}</strong><span>ORIGINS</span></div>`;$('#favoritesGrid').innerHTML=favorites.length?favorites.map(name=>`<article class="short-card" data-name="${escapeHTML(name.name)}">${heartButton(name)}<span class="tag">${escapeHTML(name.origin.toUpperCase())}</span><h3>${escapeHTML(name.name)}</h3><p>${escapeHTML(name.meaning)}</p></article>`).join(''):'<div class="empty">Your shortlist is waiting. Love a name while browsing or swiping.</div>';$('#twinGrid').innerHTML=pairs.length?pairs.map(([a,b])=>`<article class="twin-card"><span class="tag">A BALANCED PAIR</span><strong>${escapeHTML(a.name)} + ${escapeHTML(b.name)}</strong><p>${escapeHTML(a.meaning)} · ${escapeHTML(b.meaning)}</p></article>`).join(''):'<div class="empty">Save at least two names to unlock twin pair ideas.</div>';bindCards($('#view-favorites'))}
function coupleCode(){let hash=0;for(const char of state.partnerName)hash=(hash*31+char.charCodeAt(0))>>>0;return `BBN-${hash.toString(36).toUpperCase().padStart(5,'0').slice(0,5)}`}
function renderCouple(){const shared=matches();$('#partnerName').value=state.partnerName;$('#coupleCode').textContent=coupleCode();$('#coupleStats').innerHTML=`<div class="stat"><strong>${state.favorites.length}</strong><span>YOU</span></div><div class="stat"><strong>${state.partnerLikes.length}</strong><span>PARTNER</span></div><div class="stat"><strong>${shared.length}</strong><span>MATCHES</span></div>`;$('#matchesGrid').innerHTML=shared.length?shared.map(name=>`<article class="short-card" data-name="${escapeHTML(name.name)}"><span class="tag">♥ YOU BOTH LOVE</span><h3>${escapeHTML(name.name)}</h3><p>${escapeHTML(name.meaning)} · ${escapeHTML(name.origin)}</p></article>`).join(''):'<div class="empty">Keep swiping. Shared favorites will appear here—without revealing the rest of either shortlist.</div>';bindCards($('#view-couple'))}
function openName(nameValue){const name=names.find(item=>item.name===nameValue);if(!name)return;$('#modalContent').innerHTML=`<div class="modal-hero"><h2>${escapeHTML(name.name)}</h2><p>${escapeHTML(name.pronunciation)}</p><strong>${escapeHTML(name.meaning)}</strong></div><div class="modal-grid"><div class="modal-meta"><small>ORIGIN</small><strong>${escapeHTML(name.origin)}</strong></div><div class="modal-meta"><small>STYLE</small><strong>${escapeHTML(name.style)}</strong></div></div><h3>The feeling</h3><div class="vibe-wrap">${name.vibes.map(v=>`<span class="vibe active">${escapeHTML(v)}</span>`).join('')}</div><p style="color:var(--muted)">${escapeHTML(name.name)} carries a ${escapeHTML(name.vibes.join(' and ').toLowerCase())} spirit. Its ${escapeHTML(name.origin)} roots and meaning—${escapeHTML(name.meaning.toLowerCase())}—give it a story worth sharing.</p><button class="action primary" id="modalFavorite" style="width:100%">${isFavorite(name.name)?'♥ Saved to favorites':'♡ Love this name'}</button>`;$('#modalFavorite').onclick=event=>{toggleFavorite(name.name,event);openName(name.name)};$('#nameModal').showModal()}
function renderAll(){renderDiscover();renderSwipe();renderFavorites();renderCouple()}
$('#search').addEventListener('input',renderDiscover);$('#origin').addEventListener('change',renderDiscover);$$('[data-style]').forEach(button=>button.addEventListener('click',()=>{activeStyle=button.dataset.style;$$('[data-style]').forEach(item=>item.classList.toggle('active',item===button));renderDiscover()}));
$('#surprise').addEventListener('click',()=>openName(names[Math.floor(Math.random()*names.length)].name));$('#refreshPicks').addEventListener('click',()=>{pickOffset=(pickOffset+3)%names.length;renderDiscover()});$('#resetDeck').addEventListener('click',()=>{state.choices={};persist();renderSwipe();toast('Swipe deck reset')});
$('#partnerName').addEventListener('change',event=>{state.partnerName=event.target.value.trim()||'My partner';persist();renderCouple()});$('#copyCode').addEventListener('click',async()=>{await navigator.clipboard.writeText(coupleCode());toast('Couple code copied')});$('#demoPartner').addEventListener('click',()=>{state.partnerLikes=['Luna','Ezra','Kai','Elsa','Noah','Sage','Milo'];persist();renderCouple();toast('Partner picks refreshed')});
$('#closeModal').onclick=()=>$('#nameModal').close();$('#preferencesButton').onclick=()=>$('#preferencesModal').showModal();$('#closePreferences').onclick=()=>$('#preferencesModal').close();$('#savePreferences').onclick=()=>{$('#preferencesModal').close();renderDiscover();toast('Your picks are updated')};
renderVibes();renderAll();const initial=location.hash.slice(1);if(['discover','swipe','favorites','couple'].includes(initial))nav(initial);
if('serviceWorker' in navigator)navigator.serviceWorker.register('/beyond-baby-names/service-worker.js').catch(()=>{});
</script>
<script src="/assets/js/visitor-analytics.js" defer></script>
</body>
</html>
